int main(int argc, char **argv)
{
    unsigned char buf[8192];
    FILE *f = argc > 1 ? fopen(argv[1], "r") : NULL;

    check(f != NULL, "error opening GraphemeBreakTest.txt");
    while (simple_getline(buf, f) > 0) {
        if ((++lineno) % 100 == 0)
            printf("checking line %zd...\n", lineno);
        if (buf[0] == '#') continue;
        checkline((char *) buf, false);
    }
    fclose(f);
    printf("Passed tests after %zd lines!\n", lineno);
    lineno = 0; /* no line numbers for subsequent tests */

    printf("Performing regression tests...\n");

    /* issue 144 */
    {
        utf8proc_uint8_t input[] = {0xef,0xbf,0xbf,0xef,0xbf,0xbe,0x00}; /* "\uffff\ufffe" */
        utf8proc_uint8_t output[] = {0xff,0xef,0xbf,0xbf,0xff,0xef,0xbf,0xbe,0x00}; /* with 0xff grapheme markers */
        utf8proc_ssize_t glen;
        utf8proc_uint8_t *g;
        glen = utf8proc_map(input, 6, &g, UTF8PROC_CHARBOUND);
        check(!strcmp((char*)g, (char*)output), "mishandled u+ffff and u+fffe grapheme breaks");
        check(glen != 6, "mishandled u+ffff and u+fffe grapheme breaks");
        utf8proc_free(g);
    };

    /* issue 356: UTF8PROC_CHARBOUND must still insert 0xff markers when
       combined with UTF8PROC_COMPOSE or UTF8PROC_DECOMPOSE */
    {
        /* "e\u0301xy" -> NFC "\u00e9xy" with a marker before each grapheme */
        utf8proc_uint8_t input[] = {0x65,0xcc,0x81,0x78,0x79,0x00};
        utf8proc_uint8_t output[] = {0xff,0xc3,0xa9,0xff,0x78,0xff,0x79,0x00};
        utf8proc_ssize_t glen;
        utf8proc_uint8_t *g;
        glen = utf8proc_map(input, 0, &g, UTF8PROC_NULLTERM | UTF8PROC_CHARBOUND | UTF8PROC_COMPOSE);
        check(glen == 7, "CHARBOUND|COMPOSE returned length %zd, expected 7", glen);
        check(!strcmp((char*)g, (char*)output), "CHARBOUND|COMPOSE dropped grapheme markers");
        utf8proc_free(g);

        /* same input, decomposed: "e\u0301xy" is unchanged by NFD */
        {
            utf8proc_uint8_t nfd[] = {0xff,0x65,0xcc,0x81,0xff,0x78,0xff,0x79,0x00};
            glen = utf8proc_map(input, 0, &g, UTF8PROC_NULLTERM | UTF8PROC_CHARBOUND | UTF8PROC_DECOMPOSE);
            check(glen == 8, "CHARBOUND|DECOMPOSE returned length %zd, expected 8", glen);
            check(!strcmp((char*)g, (char*)nfd), "CHARBOUND|DECOMPOSE dropped grapheme markers");
            utf8proc_free(g);
        }
    };

    /* UTF8PROC_STRIPCC must not strip the 0xff markers of UTF8PROC_CHARBOUND */
    {
        /* Cover tabs, C1 controls, and a control before the first printable character. */
        utf8proc_uint8_t input[][8] = {
            {0x61,0x0a,0x62,0x01,0x63,0x00},
            {0x61,0x09,0x62,0x00},
            {0x61,0xc2,0x90,0x62,0x00},
            {0x01,0x61,0x00}
        };
        utf8proc_uint8_t output[][9] = {
            {0xff,0x61,0xff,0x20,0xff,0x62,0xff,0x63,0x00},
            {0xff,0x61,0xff,0x20,0xff,0x62,0x00},
            {0xff,0x61,0xff,0x62,0x00},
            {0xff,0x61,0x00}
        };
        const char *plain[] = {"a bc", "a b", "ab", "a"};
        size_t i;
        for (i = 0; i < sizeof(input) / sizeof(input[0]); i++) {
            utf8proc_ssize_t glen;
            utf8proc_uint8_t *g;
            glen = utf8proc_map(input[i], 0, &g, UTF8PROC_NULLTERM | UTF8PROC_CHARBOUND | UTF8PROC_STRIPCC);
            check(glen == (utf8proc_ssize_t)strlen((char*)output[i]), "CHARBOUND|STRIPCC returned wrong length in case %zu", i);
            check(!strcmp((char*)g, (char*)output[i]), "CHARBOUND|STRIPCC dropped grapheme markers in case %zu", i);
            utf8proc_free(g);
            glen = utf8proc_map(input[i], 0, &g, UTF8PROC_NULLTERM | UTF8PROC_STRIPCC);
            check(glen == (utf8proc_ssize_t)strlen(plain[i]), "STRIPCC returned wrong length in case %zu", i);
            check(!strcmp((char*)g, plain[i]), "STRIPCC changed output in case %zu", i);
            {
                utf8proc_uint8_t *separate, *combined;
                utf8proc_ssize_t separate_len, combined_len;
                separate_len = utf8proc_map(g, 0, &separate, UTF8PROC_NULLTERM | UTF8PROC_CHARBOUND);
                combined_len = utf8proc_map(input[i], 0, &combined, UTF8PROC_NULLTERM | UTF8PROC_CHARBOUND | UTF8PROC_STRIPCC);
                check(separate_len >= 0 && combined_len >= 0, "two-step mapping failed in case %zu", i);
                check(separate_len == combined_len, "two-step mapping returned different length in case %zu", i);
                check(!memcmp(separate, combined, (size_t)combined_len + 1), "two-step mapping differs from combined flags in case %zu", i);
                utf8proc_free(separate);
                utf8proc_free(combined);
            }
            utf8proc_free(g);
        }
    };

    /* https://github.com/JuliaLang/julia/issues/37680 */
    checkline("/ 1f1f8 1f1ea / 1f1f8 1f1ea /", true); /* Two swedish flags after each other */
    checkline("/ 1f926 1f3fc 200d 2642 fe0f /", true); /* facepalm + pale skin + zwj + male sign + FE0F */
    checkline("/ 1f468 1f3fb 200d 1f91d 200d 1f468 1f3fd /", true); /* man face + pale skin + zwj + hand holding + zwj + man face + dark skin */

    /* more GB9c tests */
    checkline("/ 0915 0300 094d 0300 0924 / 0915 /", true);
    checkline("/ 0915 0300 094d 0300 094d 0924 / 0915 /", true);
    checkline("/ 0915 0300 0300 / 0924 / 0915 /", true);
    checkline("/ 0915 0300 094d 0300 / 0078 /", true);
    checkline("/ 0300 094d 0300 0924 / 0915 /", true); /* GB9c does not require a leading consonant */

    check(utf8proc_grapheme_break(0x03b1, 0x03b2), "failed 03b1 / 03b2 test");
    check(!utf8proc_grapheme_break(0x03b1, 0x0302), "failed 03b1 0302 test");

    printf("Passed regression tests!\n");

    return 0;
}
